fn check_lamp_arrangement(r: i8, g: i8, b: i8) -> bool {
    // Promote to a wider integer type to avoid potential overflow when summing.
    let r = r as i32;
    let g = g as i32;
    let b = b as i32;

    let total = r + g + b;
    let max_count = r.max(g).max(b);

    // The arrangement is possible if and only if
    // 2 * max_count <= total + 1
    2 * max_count <= total + 1
}

