    #[test]
    fn test_possible_arrangements() {
        // Equal counts always work.
        assert!(check_lamp_arrangement(3, 3, 3));
        // One slightly larger but still feasible.
        assert!(check_lamp_arrangement(4, 2, 2)); // 4*2 = 8 <= 8+1 = 9
        assert!(check_lamp_arrangement(5, 4, 1)); // 2*5 = 10 <= 10+1 = 11
    }

    #[test]
    fn test_impossible_arrangements() {
        // One count too large to interleave.
        assert!(!check_lamp_arrangement(5, 1, 1)); // 2*5 = 10 > 7+1 = 8
        assert!(!check_lamp_arrangement(10, 2, 3)); // 2*10 = 20 > 15+1 = 16
    }

